import Link from "next/link";

type LogoProps = {
  /** Rendered height of the wordmark in px (per spec: 23–24). */
  size?: number;
  /** Text color context. The "O" dot stays gold in both. */
  variant?: "light" | "dark";
  /** When true, renders as a Home link with an accessible label. */
  asLink?: boolean;
  className?: string;
};

