export default function Logo({
  size = 23,
  variant = "light",
  asLink = false,
  className = "",
}: LogoProps) {
  const textColor = variant === "dark" ? "text-paper" : "text-ink";

  const mark = (
    <svg
      aria-hidden="true"
      viewBox={VIEWBOX}
      height={size}
      width={Math.round(size * ASPECT)}
      className={`block shrink-0 ${textColor} ${className}`}
      focusable="false"
    >
      <path fill="currentColor" d={LETTERS} />
      <path fill="#D89A2E" d={DOT} />
      <path fill="currentColor" d={BAR} />
    </svg>
  );

  if (asLink) {
    return (
      <Link
        href="/"
        aria-label="CREDOM — home"
        className="inline-flex min-w-0 shrink items-center"
      >
        {mark}
      </Link>
    );
  }

  return mark;
}
